  "wh2_dlc11_army_abilities_shanty_verse_2": {"id":"wh2_dlc11_army_abilities_shanty_verse_2","kind":"ability","name":"Shanty: Second Verse","description":"\"Now that we have the ocean so slow, put the sails away and prepare to row; for the monster hunts and its prey should shiver, ever since the Vortex went a-quiver!\"","icon":"ui/battle ui/ability_icons/wh2_dlc11_army_abilities_shanty_verse_1.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"defense":{"add":30}}},
