  "wh2_dlc12_unit_passive_blade_swirl": {"id":"wh2_dlc12_unit_passive_blade_swirl","kind":"ability","name":"Blade Swirl","description":"Enemy blades and missiles are easily deflected by the whirling metal, which acts like a defensive barrier when activated.","icon":"ui/battle ui/ability_icons/wh2_dlc12_unit_passive_blade_swirl.png","placement":"attack","target":"self","passive":true,"polarity":"positive","modifiers":{"contact_effect":"wh_dlc06_unit_contact_sundered_armour"}},
