  "wh2_main_army_abilities_mors_clanstone": {"id":"wh2_main_army_abilities_mors_clanstone","kind":"ability","name":"Mors Clanstone","description":"On the battlefield, Clan Mors' sacred Warpstones instil their upstart warriors with even greater stamina and skill.","icon":"ui/battle ui/ability_icons/wh2_main_army_abilities_mors_clanstone.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.5}}}},
