  "wh2_main_character_abilities_assassins_trophy": {"id":"wh2_main_character_abilities_assassins_trophy","kind":"ability","name":"Assassin's Trophy","description":"It should be no great surprise that those already adept in the art of silent death continue to improve with time and practice.","icon":"ui/battle ui/ability_icons/wh2_main_character_abilities_assassins_trophy.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"attack":{"add":-24},"defense":{"add":-24}}},
