  "wh2_main_character_abilities_dark_venom": {"id":"wh2_main_character_abilities_dark_venom","kind":"ability","name":"Dark Venom","description":"A victim of Dark Venom knows only a drawn-out and agonising death.","icon":"ui/battle ui/ability_icons/wh2_main_character_abilities_dark_venom.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"normal":{"mult":1.9}}}},
