  "wh2_main_character_abilities_witchbrew": {"id":"wh2_main_character_abilities_witchbrew","kind":"ability","name":"Witchbrew","description":"Distilled from the blood of Hag Queens, this evil brew drives imbibers into an ecstasy of destruction.","icon":"ui/battle ui/ability_icons/wh2_main_character_abilities_witchbrew.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"normal":{"mult":1.5},"piercing":{"mult":1.5}},"attack":{"add":24}}},
  "wh2_main_character_passive_aura_of_pestilence": {"id":"wh2_main_character_passive_aura_of_pestilence","kind":"ability","name":"Aura of Pestilence","description":"All around are caught in a deadly miasma of virulent disease that rips through their bodies with vile momentum.","icon":"ui/battle ui/ability_icons/wh2_main_character_passive_aura_of_pestilence.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"attack":{"add":-5}}},
  "wh2_main_character_passive_horn_of_isha": {"id":"wh2_main_character_passive_horn_of_isha","kind":"ability","name":"Horn of Isha","description":"The horn is fashioned from a single pearl-white seashell. When winded, it can split the veil between worlds and grant a blessing.","icon":"ui/battle ui/ability_icons/wh2_main_character_passive_horn_of_isha.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"attack":{"add":5}}},
  "wh2_main_faction_abilities_murderous_mastery": {"id":"wh2_main_faction_abilities_murderous_mastery","kind":"ability","name":"Murderous Mastery","description":"It is through killing that Dark Elves rise above other beings. Once engulfed in enough bloodshed, they will often feel their murderous prowess increase, as if Khaine himself was guiding the blades of his disciples.","icon":"ui/battle ui/ability_icons/wh2_main_faction_abilities_murderous_mastery.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"attack":{"mult":1.25}}},
  "wh2_main_faction_abilities_murderous_prowess": {"id":"wh2_main_faction_abilities_murderous_prowess","kind":"ability","name":"Murderous Prowess","description":"Slaughter! There is no greater glorification of Khaine, the God of Murder, and no more popular form of worship – or indeed daily exercise – amongst the Dark Elves.","icon":"ui/battle ui/ability_icons/wh2_main_faction_abilities_murderous_prowess.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"attack":{"mult":1.25}}},
