  "wh2_main_item_abilities_the_bane_shield": {"id":"wh2_main_item_abilities_the_bane_shield","kind":"ability","name":"The Bane Shield","description":"A magnificent shield emblazoned with a coiled serpent, allowing its wielder to benefit from even greater protection.","icon":"ui/battle ui/ability_icons/wh2_main_item_abilities_the_bane_shield.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"armor":{"add":30}}},
