  "wh3_dlc26_unit_passive_keep_em_ungry": {"id":"wh3_dlc26_unit_passive_keep_em_ungry","kind":"ability","name":"Keep Em Ungry","icon":"ui/battle ui/ability_icons/wh3_dlc26_unit_passive_keep_em_ungry.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"bonus_v_infantry":{"add":32},"normal":{"mult":1.75},"piercing":{"mult":1.75}}}},
