  "wh3_dlc26_unit_passive_piggy_back_joust": {"id":"wh3_dlc26_unit_passive_piggy_back_joust","kind":"ability","name":"Piggyback Joust!","description":"These Gnoblars love to joust each other when away from the battlefield, but will more-than happily practice on live foes to hone their, er, chops.","icon":"ui/battle ui/ability_icons/wh3_dlc26_unit_passive_piggy_back_joust.png","placement":"attack","target":"self","passive":true,"polarity":"positive","modifiers":{"contact_effect":"wh3_main_unit_contact_disorientated"}},
  "wh3_dlc26_unit_passive_runes_of_binding": {"id":"wh3_dlc26_unit_passive_runes_of_binding","kind":"ability","name":"Runes of Binding","description":"The fate of a Slaughterbrute is bound to its master. If its master lives, it kills at his behest. If not, it simply kills.","icon":"ui/battle ui/ability_icons/wh3_dlc26_unit_passive_runes_of_binding.png","placement":"attack","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"is_magical":true}}},
