  "wh3_dlc26_unit_passive_uncanny_coordination": {"id":"wh3_dlc26_unit_passive_uncanny_coordination","kind":"ability","name":"Uncanny Coordination","description":"Maybe it's herd mentality, but in greater numbers, Gnoblars are a far more unified fighting force.","icon":"ui/battle ui/ability_icons/wh3_dlc26_unit_passive_uncanny_coordination.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"defense":{"add":8}}},
