  "wh3_dlc27_lord_passive_naval_discipline": {"id":"wh3_dlc27_lord_passive_naval_discipline","kind":"ability","name":"Naval Discipline","description":"By the call of its mighty Sea Lords, the Asur fleet demonstrates why it is renowned as the greatest naval power in the world, its training superior to all others.","icon":"ui/battle ui/ability_icons/wh3_dlc27_lord_passive_naval_discipline.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"defense":{"add":5}}},
  "wh3_dlc27_qb_unit_abilities_ascendants_hubris": {"id":"wh3_dlc27_qb_unit_abilities_ascendants_hubris","kind":"ability","name":"Ascendant's Hubris","description":"To kill the Ascendant is to kill his pride. But while he lives, it is far greater than others of his kin.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_ascendants_hubris.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":3},"normal":{"mult":3}},"defense":{"add":25},"attack":{"add":25}}},
  "wh3_dlc27_qb_unit_abilities_bitter_sting": {"id":"wh3_dlc27_qb_unit_abilities_bitter_sting","kind":"ability","name":"Bitter Sting","description":"The surest mark of enduring malice is prolonging one's depredations on the weak and weary.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_bitter_sting.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"attack":{"add":-24},"defense":{"add":-24}}},
  "wh3_dlc27_qb_unit_abilities_bloodsport": {"id":"wh3_dlc27_qb_unit_abilities_bloodsport","kind":"ability","name":"Bloodsport","description":"The growing piles of the dead will serve as a source of satisfaction for the twisted, rudimentary self-awareness in the depths of this Preyton's mind.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_bloodsport.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"attack":{"mult":4},"damage":{"piercing":{"mult":4},"normal":{"mult":4}}}},
  "wh3_dlc27_qb_unit_abilities_brutality": {"id":"wh3_dlc27_qb_unit_abilities_brutality","kind":"ability","name":"Brutality","description":"This Ghorgon's body, if damaged enough, can be induced to feed upon itself. Unfortunately, this only fuels its ferocious hunger.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_brutality.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"normal":{"mult":3}}}},
  "wh3_dlc27_qb_unit_abilities_corrosive_coating": {"id":"wh3_dlc27_qb_unit_abilities_corrosive_coating","kind":"ability","name":"Corrosive Coating","description":"The slime fends off the mundane. The source of the creature's \"blessings\" fends off anything else that comes into contact with it.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_corrosive_coating.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"physical":{"add":25}}}},
  "wh3_dlc27_qb_unit_abilities_frenzied_challenge": {"id":"wh3_dlc27_qb_unit_abilities_frenzied_challenge","kind":"ability","name":"Frenzied Challenge","description":"Faced with this creature's challenge, one either fights or flees. Yet who would flee and doom themselves to nightmares of becoming its meal? Fight it is.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_frenzied_challenge.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"defense":{"add":-24}}},
  "wh3_dlc27_qb_unit_abilities_guttural_roar": {"id":"wh3_dlc27_qb_unit_abilities_guttural_roar","kind":"ability","name":"Guttural Roar","description":"This is not a warning for evildoers to go. It is a promise of what is to come.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_guttural_roar.png","placement":"effects","target":"self","passive":false,"polarity":"negative","modifiers":{"damage":{"normal":{"mult":0.85}},"defense":{"add":-16}}},
  "wh3_dlc27_qb_unit_abilities_insatiable_hunger": {"id":"wh3_dlc27_qb_unit_abilities_insatiable_hunger","kind":"ability","name":"Insatiable Hunger","description":"The Carrion Eater's hunger breaks down any form resistance, beginning with the victim's means of protection and ending with the final hopeless flutters of its body.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_insatiable_hunger.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":3}}}},
  "wh3_dlc27_qb_unit_abilities_petrifying_aura": {"id":"wh3_dlc27_qb_unit_abilities_petrifying_aura","kind":"ability","name":"Petrifying Aura","description":"In a depraved twist of its master's will, those who return this creature's baleful gaze retain torturous mobility… for a while.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_petrifying_aura.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"resistance":{"magic":{"add":-20}}}},
  "wh3_dlc27_qb_unit_abilities_razor_sharp_teeth": {"id":"wh3_dlc27_qb_unit_abilities_razor_sharp_teeth","kind":"ability","name":"Diligent Chewing","description":"It is extremely unlikely for the Runt to choke on anything that enters his maw. Yet something has taught him to be thorough nevertheless.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_razor_sharp_teeth.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":3}}}},
  "wh3_dlc27_qb_unit_abilities_runt_of_the_litter": {"id":"wh3_dlc27_qb_unit_abilities_runt_of_the_litter","kind":"ability","name":"Runt of the Litter","description":"Not knowing one's size comes hand in hand with not knowing one's strength. The Runt needn't skimp on either when threatened.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_runt_of_the_litter.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"physical":{"add":50}},"defense":{"add":48}}},
  "wh3_dlc27_qb_unit_abilities_too_stubborn_to_die": {"id":"wh3_dlc27_qb_unit_abilities_too_stubborn_to_die","kind":"ability","name":"Too Stubborn to Die","description":"Hate, if strong enough, outlives everything. There is no hate greater than that for a singular rival who carries a promise of death.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_too_stubborn_to_die.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":50}}}},
  "wh3_dlc27_qb_unit_abilities_undoubtful_pride": {"id":"wh3_dlc27_qb_unit_abilities_undoubtful_pride","kind":"ability","name":"Overbearing Pride","description":"By his nature and long-lived experience, the Wise One is immune to paltry stratagems, standing his ground and wreaking havoc no matter what.","icon":"ui/battle ui/ability_icons/wh3_dlc27_qb_unit_abilities_undoubtful_pride.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"physical":{"add":25}}}},
