  "wh3_dlc27_unit_abilities_consuming_hatred": {"id":"wh3_dlc27_unit_abilities_consuming_hatred","kind":"ability","name":"All-Consuming Hatred","description":"The innate hatred carried within a Preyton makes it despise itself almost as much as its foes, whose attacks are repaid with added enmity.","icon":"ui/battle ui/ability_icons/wh3_dlc27_unit_abilities_consuming_hatred.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"defense":{"add":-12}}},
