  "wh3_dlc29_weapon_active_hammer_axe_of_skoll": {"id":"wh3_dlc29_weapon_active_hammer_axe_of_skoll","kind":"ability","name":"Hammer-axe of Skoll","description":"The Hammer-axe of Skoll is not just a symbol of duty, but an effective means of carrying it out – particularly when smiting your adversaries.","icon":"ui/battle ui/ability_icons/wh3_dlc29_weapon_active_hammer_axe_of_skoll.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.75},"normal":{"mult":1.75}},"attack":{"add":24}}},
