  "wh3_main_army_abilities_horn_of_khorne": {"id":"wh3_main_army_abilities_horn_of_khorne","kind":"ability","name":"Horn of Khorne","description":"An extra horn bursts forth from the warriors' foreheads, increasing the possibility that attacks will be successful, and in turn the likelihood of the kill.","icon":"ui/battle ui/ability_icons/wh3_main_army_abilities_horn_of_khorne.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24}}},
