  "wh3_main_ascendant_metal_acendancy": {"id":"wh3_main_ascendant_metal_acendancy","kind":"ability","name":"Metal Ascendancy","description":"The Wind of Chamon – clad yourself in metal and let this energy fortify your forces.","icon":"ui/battle ui/ability_icons/icon_som_passive_metal.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"armor":{"add":20}}},
