  "wh3_main_banner_passive_rune_maw": {"id":"wh3_main_banner_passive_rune_maw","kind":"ability","name":"Rune Maw","description":"The Rune Maw constantly emits a low growl that rises to a predatory roar when it detects magic, spitting the arcane energies back out with a loud belch.","icon":"ui/battle ui/ability_icons/wh3_main_banner_passive_rune_maw.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"magic":{"add":10}}}},
