  "wh3_main_character_abilities_locus_of_abjuration": {"id":"wh3_main_character_abilities_locus_of_abjuration","kind":"ability","name":"Locus of Abjuration","description":"The Herald's dedication to Khorne exceeds all else, enabling them to resist magical attack via their unnatural, Daemonic aura of rancorous disdain.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_abjuration.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"magic":{"add":65}}}},
  "wh3_main_character_abilities_locus_of_beguilement": {"id":"wh3_main_character_abilities_locus_of_beguilement","kind":"ability","name":"Locus of Beguilement","description":"\"What? Why are we…? Er, where am I? Who am I? Why am I?!\"","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_beguilement.png","placement":"effects","target":"self","passive":false,"polarity":"negative","modifiers":{"defense":{"add":-24}}},
  "wh3_main_character_abilities_locus_of_fury": {"id":"wh3_main_character_abilities_locus_of_fury","kind":"ability","name":"Locus of Fury","description":"Anger is an energy – the most powerful force in all creation. Never doubt it.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_fury.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"normal":{"mult":1.25},"piercing":{"mult":1.25}}}},
  "wh3_main_character_abilities_locus_of_grace": {"id":"wh3_main_character_abilities_locus_of_grace","kind":"ability","name":"Locus of Grace","description":"The warrior glides with a beauteous, smooth elegance that enables them to simply avoid blows as if in slow motion, for the Dark Prince has blessed their every move.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_grace.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"physical":{"add":22}},"defense":{"add":24}}},
  "wh3_main_character_abilities_locus_of_virulence": {"id":"wh3_main_character_abilities_locus_of_virulence","kind":"ability","name":"Locus of Virulence","description":"Wholly and perversely against nature, those warriors elevated to Daemonhood by the Fly Lord will prosper and surge through His disgusting gifts and boons.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_virulence.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.25},"normal":{"mult":1.25}},"attack":{"add":24}}},
  "wh3_main_character_abilities_locus_of_wrath": {"id":"wh3_main_character_abilities_locus_of_wrath","kind":"ability","name":"Locus of Wrath","description":"Khorne's Heralds find that the pure, unadulterated ire channelled directly from the Blood God Himself drives their own impetuous vehemence to even greater heights.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_locus_of_wrath.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":40}}},
  "wh3_main_character_abilities_no_escape": {"id":"wh3_main_character_abilities_no_escape","kind":"ability","name":"No Escape","description":"\"Enough of that flailing about, worm. Now you die!\"","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_no_escape.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"defense":{"add":-40}}},
  "wh3_main_character_abilities_tors_battle_hymn": {"id":"wh3_main_character_abilities_tors_battle_hymn","kind":"ability","name":"Tor's Battle Hymn","description":"\"Thunder is strong and lightning is death, with Tor's wrath a flash-bolt takes their breath!\"","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_tors_battle_hymn.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":40}}},
  "wh3_main_character_abilities_unyielding_defender": {"id":"wh3_main_character_abilities_unyielding_defender","kind":"ability","name":"Unyielding Defence","description":"Never give up, never surrender, no matter what happens. Choose death over the way of the craven.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_unyielding_defender.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"defense":{"add":24}}},
  "wh3_main_character_passive_bellyslapper": {"id":"wh3_main_character_passive_bellyslapper","kind":"ability","name":"Bellyslapper","description":"An Ogre whose proclivity is for slapping his body, making his flesh ripple and repel the foe.","icon":"ui/battle ui/ability_icons/wh3_main_character_passive_bellyslapper.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"attack":{"add":-8}}},
  "wh3_main_character_passive_deathcheater": {"id":"wh3_main_character_passive_deathcheater","kind":"ability","name":"Deathcheater","description":"Assuming death is coming for you via magical means, there's a high chance you'll cheat it... this time at least.","icon":"ui/battle ui/ability_icons/wh3_main_character_abilities_deathcheater.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":90}}}},
  "wh3_main_character_passive_enduring_devotion": {"id":"wh3_main_character_passive_enduring_devotion","kind":"ability","name":"Enduring Devotion","description":"When he wills it so, those loyal to the Patriarch will find their minds and bodies bolstered against attack.","icon":"ui/battle ui/ability_icons/wh3_main_character_passive_enduring_devotion.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"defense":{"add":5}}},
  "wh3_main_character_passive_grandfeaster": {"id":"wh3_main_character_passive_grandfeaster","kind":"ability","name":"Grandfeaster","description":"The greatest of Big Names. There have been few Grandfeasters in all the Ogre Kingdoms! All around are steeled for the fight.","icon":"ui/battle ui/ability_icons/wh3_main_character_passive_grandfeaster.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"attack":{"add":8}}},
