  "wh3_main_siege_defender": {"id":"wh3_main_siege_defender","kind":"ability","name":"Siege Defender","description":"You fight harder for what is yours.","icon":"ui/battle ui/ability_icons/wh3_main_siege_defender.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"defense":{"mult":1.15}}},
