  "wh3_main_spell_bound_cascading_fire_cloak": {"id":"wh3_main_spell_bound_cascading_fire_cloak","kind":"ability","name":"Bound Cascading Fire Cloak","icon":"ui/battle ui/ability_icons/wh_main_spell_fire_cascading_fire_cloak.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.25}},"defense":{"add":24}}},
