  "wh3_main_spell_bound_harmonic_convergence": {"id":"wh3_main_spell_bound_harmonic_convergence","kind":"ability","name":"Bound Harmonic Convergence","icon":"ui/battle ui/ability_icons/wh_main_spell_heavens_harmonic_convergence.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24},"defense":{"add":24}}},
  "wh3_main_spell_bound_phas_protection": {"id":"wh3_main_spell_bound_phas_protection","kind":"ability","name":"Pha's Protection","icon":"ui/battle ui/ability_icons/wh_main_spell_light_phas_protection.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"armor":{"add":30},"defense":{"add":24}}},
  "wh3_main_spell_bound_plague_of_rust": {"id":"wh3_main_spell_bound_plague_of_rust","kind":"ability","name":"Plague of Rust","description":"Utilising the alchemical Lore of Metal, the Wizard commands the foe's armour to rot, causing it to shed away in clouds of tiny flakes.","icon":"ui/battle ui/ability_icons/wh_main_spell_metal_plague_of_rust.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"armor":{"add":-30}}},
  "wh3_main_spell_bound_the_curse_of_anraheir": {"id":"wh3_main_spell_bound_the_curse_of_anraheir","kind":"ability","name":"The Curse of Anraheir","icon":"ui/battle ui/ability_icons/wh_dlc03_spell_beasts_the_curse_of_anraheir.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"defense":{"add":-24},"attack":{"add":-24}}},
  "wh3_main_spell_bound_transmutation_of_lead": {"id":"wh3_main_spell_bound_transmutation_of_lead","kind":"ability","name":"Transmutation of Lead","description":"Transformed into lead, the foe’s weapons become heavy, cumbersome, and almost impossible to wield in battle, let alone use effectively.","icon":"ui/battle ui/ability_icons/wh_main_spell_metal_transmutation_of_lead.png","placement":"effects","target":"enemy","passive":false,"polarity":"negative","modifiers":{"damage":{"normal":{"mult":0.7}},"attack":{"add":-24}}},
  "wh3_main_spell_great_maw_bullgorger": {"id":"wh3_main_spell_great_maw_bullgorger","kind":"ability","name":"Bullgorger","description":"Devouring the heart of a bull Rhinox or Mournfang, raw vitality is projected into the Great Maw, increasing the ferocity of the Ogres' attacks.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_bullgorger.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24},"damage":{"piercing":{"mult":1.25}}}},
  "wh3_main_spell_great_maw_bullgorger_upgraded": {"id":"wh3_main_spell_great_maw_bullgorger_upgraded","kind":"ability","name":"Bullgorger Upgraded","description":"Devouring the heart of a bull Rhinox or Mournfang, raw vitality is projected into the Great Maw, increasing the ferocity of the Ogres' attacks.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_bullgorger.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24},"damage":{"piercing":{"mult":1.25}}}},
  "wh3_main_spell_great_maw_toothcracker": {"id":"wh3_main_spell_great_maw_toothcracker","kind":"ability","name":"Toothcracker","description":"By consuming a hunk of tooth-breaking granite, the spellcaster bestows the rock's resilience and the sturdiness of the mountains themselves into his brethren.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_toothcracker.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"armor":{"add":30}}},
  "wh3_main_spell_great_maw_toothcracker_upgraded": {"id":"wh3_main_spell_great_maw_toothcracker_upgraded","kind":"ability","name":"Toothcracker Upgraded","description":"By consuming a hunk of tooth-breaking granite, the spellcaster bestows the rock's resilience and the sturdiness of the mountains themselves into his brethren.","icon":"ui/battle ui/ability_icons/wh3_main_spell_great_maw_toothcracker.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"armor":{"add":30}}},
  "wh3_main_spell_ice_crystal_sanctuary": {"id":"wh3_main_spell_ice_crystal_sanctuary","kind":"ability","name":"Crystal Sanctuary","description":"Constructs are woven from the ice itself, sheltering Kislev's courageous soldiers from the onslaught of their foes.","icon":"ui/battle ui/ability_icons/wh3_main_spell_ice_crystal_sanctuary.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":80}}}},
  "wh3_main_spell_ice_crystal_sanctuary_upgraded": {"id":"wh3_main_spell_ice_crystal_sanctuary_upgraded","kind":"ability","name":"Crystal Sanctuary Upgraded","description":"Constructs are woven from the ice itself, sheltering Kislev's courageous soldiers from the onslaught of their foes.","icon":"ui/battle ui/ability_icons/wh3_main_spell_ice_crystal_sanctuary.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":80}}}},
