  "wh3_main_spell_tzeentch_treason_of_tzeentch_upgraded": {"id":"wh3_main_spell_tzeentch_treason_of_tzeentch_upgraded","kind":"ability","name":"Treason of Tzeentch Upgraded","description":"The spellcaster whispers into the enemies' minds, subtly stoking the fires of mistrust and treachery.","icon":"ui/battle ui/ability_icons/wh3_main_spell_tzeentch_treason_of_tzeentch.png","placement":"effects","target":"self","passive":false,"polarity":"negative","modifiers":{"attack":{"add":-24}}},
  "wh3_main_spell_yang_jade_shield": {"id":"wh3_main_spell_yang_jade_shield","kind":"ability","name":"Jade Shield","description":"A blazing wind of light creates a potent barrier against harm, as well as invigorating all living things who shelter beneath its protection.","icon":"ui/battle ui/ability_icons/wh3_main_spell_yang_jade_shield.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":44}}}},
