  "wh3_main_spell_yang_might_of_heaven_and_earth": {"id":"wh3_main_spell_yang_might_of_heaven_and_earth","kind":"ability","name":"Might of Heaven & Earth","description":"Soldiers present are filled with the pure power of the Yang, which makes them stronger and more skilled, and their weapons blaze with celestial energy.","icon":"ui/battle ui/ability_icons/wh3_main_spell_yang_might_of_heaven_and_earth.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.25},"normal":{"mult":1.25},"is_magical":true,"is_fire":true},"attack":{"add":24}}},
