  "wh3_main_unit_abilities_mimic_battle_harmony_elf": {"id":"wh3_main_unit_abilities_mimic_battle_harmony_elf","kind":"ability","name":"Mirror (Battle Harmony: Elf)","description":"There must be balance in all things: haughtiness or decorum; thrusted spear or well-aimed arrow; defensive line or controlled assault This ability is being mirrored using knowledge gained from a prisoner interrogation in Athel Tamarha.","icon":"ui/battle ui/ability_icons/wh3_main_unit_passive_battle_harmony_yang.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"defense":{"add":6}}},
  "wh3_main_unit_abilities_stun_bomb": {"id":"wh3_main_unit_abilities_stun_bomb","kind":"ability","name":"Heaven's Flash","description":"Ignition of this gunpowder mixture causes shavings to quickly scatter into a foul, painful cloud, leaving enemies vulnerable to the cut-and-thrust of close quarters combat.","icon":"ui/battle ui/ability_icons/wh3_main_unit_abilities_stun_bomb.png","placement":"effects","target":"self","passive":false,"polarity":"negative","modifiers":{"attack":{"add":-24},"defense":{"add":-24}}},
