  "wh3_survival_khorne_1_icon_of_ruin": {"id":"wh3_survival_khorne_1_icon_of_ruin","kind":"ability","name":"The Icon of Ruin","description":"The alliance that controls this Ruinous monument uses the power of the Blood God to shatter the armour of their enemies.","icon":"ui/battle ui/ability_icons/wh3_survival_khorne_ruin.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"armor":{"mult":0.8},"defense":{"mult":0.9}}},
  "wh3_survival_khorne_2_icon_of_blood": {"id":"wh3_survival_khorne_2_icon_of_blood","kind":"ability","name":"The Icon of Blood","description":"The alliance that controls this bloodforged edifice draws on the wrath of Khorne to drive demoralised enemies into a blind fury, attacking friend and foe alike.","icon":"ui/battle ui/ability_icons/wh3_survival_khorne_blood.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"attack":{"mult":0.9}}},
