  "wh3_survival_nurgle_1_sapping_tree": {"id":"wh3_survival_nurgle_1_sapping_tree","kind":"ability","name":"The Sapping Tree","description":"Only the decaying flourish in Grandfather's foul garden; there is no place for the healthy here.","icon":"ui/battle ui/ability_icons/wh3_survival_nurgle_garden.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"resistance":{"magic":{"add":-15}},"attack":{"mult":0.9},"defense":{"mult":0.9}}},
