  "wh3_survival_slaanesh_1_scent_of_vainglory": {"id":"wh3_survival_slaanesh_1_scent_of_vainglory","kind":"ability","name":"The Scent of Vainglory","description":"Unit cohesion and martial discipline go to the wall once you realise you're the greatest warrior present who needs no assistance from anyone.","icon":"ui/battle ui/ability_icons/wh3_survival_slaanesh_vainglory.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"attack":{"mult":0.9}}},
  "wh3_survival_slaanesh_2_scent_of_joy": {"id":"wh3_survival_slaanesh_2_scent_of_joy","kind":"ability","name":"The Scent of Joy","description":"No resistance is possible when experiencing a wave of pure, unadulterated delight.","icon":"ui/battle ui/ability_icons/wh3_survival_slaanesh_joy.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"damage":{"normal":{"mult":0.9}},"defense":{"mult":0.9}}},
  "wh3_survival_slaanesh_3_scent_of_indolency": {"id":"wh3_survival_slaanesh_3_scent_of_indolency","kind":"ability","name":"The Scent of Indolency","description":"\"Honestly… what's the point anymore? Does anyone know? The battle? Pfft…\"","icon":"ui/battle ui/ability_icons/wh3_survival_slaanesh_perfection.png","placement":"effects","target":"self","passive":true,"polarity":"negative","modifiers":{"attack":{"mult":0.9},"defense":{"mult":0.9}}},
