  "wh_dlc06_lord_abilities_mighty_oath_stone": {"id":"wh_dlc06_lord_abilities_mighty_oath_stone","kind":"ability","name":"Mighty Oath Stone","description":"Belegar carries his enormous Oath Stone everywhere. In dire times, he stands tauntingly atop it to fight to the end.","icon":"ui/battle ui/ability_icons/wh_dlc06_character_abilities_oath_stone.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"defense":{"add":24}}},
