  "wh_dlc06_lord_abilities_spite_of_da_bad_moon": {"id":"wh_dlc06_lord_abilities_spite_of_da_bad_moon","kind":"ability","name":"Spite of Da Bad Moon","description":"Da Bad Moon offers heightened pugnacity to its weird and disgusting worshippers, spurring them to dish out even more pain.","icon":"ui/battle ui/ability_icons/wh_dlc06_character_abilities_spite_of_da_bad_moon.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"piercing":{"mult":1.25},"bonus_v_large":{"add":16},"normal":{"mult":1.25}}}},
