  "wh_dlc06_quest_abilities_grand_faiths_bastion": {"id":"wh_dlc06_quest_abilities_grand_faiths_bastion","kind":"ability","name":"Greater Faith Bastion","description":"Swiftly invoking the protection of Sigmar or Ulric blesses the implorer with a shield of godly faith, should they prove worthy.","icon":"ui/battle ui/ability_icons/wh_main_hero_abilities_faiths_bastion.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":90}}}},
