  "wh_dlc07_lord_abilities_favour_of_the_fay": {"id":"wh_dlc07_lord_abilities_favour_of_the_fay","kind":"ability","name":"Favour of the Fay","description":"\"I didn't know how empty was my soul... until it was filled.\"","icon":"ui/battle ui/ability_icons/wh_dlc07_lord_abilities_favour_of_the_fay.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":40}}},
