  "wh_main_spell_bound_bironas_timewarp": {"id":"wh_main_spell_bound_bironas_timewarp","kind":"ability","name":"Birona's Timewarp","description":"The Wizard infuses his allies with Light Magic, freeing them from the passage of time and speeding up their actions.","icon":"ui/battle ui/ability_icons/wh_main_spell_light_bironas_timewarp.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24}}},
  "wh_main_spell_bound_book_of_arkhan": {"id":"wh_main_spell_bound_book_of_arkhan","kind":"ability","name":"Book of Arkhan","description":"Friendly units targeted by the caster are filled with magical energy, making them even more aggressive!","icon":"ui/battle ui/ability_icons/wh_main_spell_bound_book_of_arkhan.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24}}},
  "wh_main_spell_bound_hammer_of_sigmar": {"id":"wh_main_spell_bound_hammer_of_sigmar","kind":"ability","name":"Hammer of Sigmar","description":"The Warrior Priest implores Sigmar to imbue him with a modicum of divine strength, and now his hammer glows bright with power!","icon":"ui/battle ui/ability_icons/wh_main_spell_bound_hammer_of_sigmar.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"attack":{"add":24}}},
  "wh_main_spell_bound_shield_of_faith": {"id":"wh_main_spell_bound_shield_of_faith","kind":"ability","name":"Shield of Faith","description":"The Warrior Priest’s faith manifests in the form of a shield as hard as castle-forged steel.","icon":"ui/battle ui/ability_icons/wh_main_spell_bound_shield_of_faith.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":20}}}},
