  "wh_main_unit_abilities_black_nimbus": {"id":"wh_main_unit_abilities_black_nimbus","kind":"ability","name":"Black Nimbus","description":"A pulsing nimbus of darkness envelops the Black Coach, making it sleeker and more resistant to enemies.","icon":"ui/battle ui/ability_icons/wh_main_unit_abilities_black_nimbus.png","placement":"effects","target":"self","passive":true,"polarity":"positive","modifiers":{"resistance":{"ward_save":{"add":40}}}},
