  "wh_main_unit_abilities_entrenchment": {"id":"wh_main_unit_abilities_entrenchment","kind":"ability","name":"Entrenchment","description":"All the sons of Grungni can dig-in, enabling them to better resist physical attacks from the foe. Any missile attacks they can make are also improved.","icon":"ui/battle ui/ability_icons/wh_main_unit_abilities_entrenchment.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"resistance":{"physical":{"add":20}}}},
  "wh_main_unit_abilities_killing_blow": {"id":"wh_main_unit_abilities_killing_blow","kind":"ability","name":"Killing Blow","description":"Such champions are adept at delivering a Killing Blow, depriving the foe of life with a single, powerful attack.","icon":"ui/battle ui/ability_icons/wh_main_unit_abilities_killing_blow.png","placement":"effects","target":"self","passive":false,"polarity":"positive","modifiers":{"damage":{"normal":{"mult":1.25},"piercing":{"mult":1.25}}}},
